"""Publish actual fixed-camera renders and reference images without retouching."""
from pathlib import Path
import json,shutil
from PIL import Image,ImageDraw,ImageFont,ImageOps
ROOT=Path('C:/GrandTour');QA=ROOT/'Saved/LidarAuthoringQA/RS7';OUT=ROOT/'Art/Export/LidarStudy/CohesiveStyle/Review';OUT.mkdir(parents=True,exist_ok=True)
font=lambda n:ImageFont.truetype('C:/Windows/Fonts/segoeui.ttf',n)
for label in ['firewatch-medium','evergreen']:
 r=json.loads((QA/f'runtime-{label}.json').read_text(encoding='utf-8-sig'));assert r['exit_code']==0 and r['render_validation_passed']
 for v in ['V01','V02','V03','G01']:shutil.copy2(QA/f'{label}-{v}.png',OUT/f'{label}-{v}.png')
for src,name in [(ROOT/'Art/References/StylizedLongViews/firewatch.jpg','firewatch.jpg'),(ROOT/'Art/References/ValleyDepthCoverage/original-scene.jpg','original.jpg')]:shutil.copy2(src,OUT/name)
for v in ['V02','V03']:
 canvas=Image.new('RGB',(1960,1240),'#11201e');d=ImageDraw.Draw(canvas)
 d.text((28,15),'LIDAR / WARM LIGHT, COOL EVERGREEN VALLEYS',font=font(31),fill='#eee9d8')
 d.text((28,59),'Actual game views • same camera and exposure • unchanged planting and terrain',font=font(21),fill='#b9c7b9')
 for i,(title,name) in enumerate([('PREVIOUS MEDIUM',f'firewatch-medium-{v}.png'),('COORDINATED PALETTE + CROWN LIGHTING',f'evergreen-{v}.png'),('FIREWATCH / broad shapes and layered distance','firewatch.jpg'),('ORIGINAL REFERENCE / richness and warm earth','original.jpg')]):
  x=28+i%2*970;y=102+i//2*565;d.text((x,y),title,font=font(22),fill='#eee9d8')
  im=ImageOps.contain(Image.open(OUT/name).convert('RGB'),(934,525),Image.Resampling.LANCZOS);canvas.paste(im,(x+(934-im.width)//2,y+35+(525-im.height)//2))
 canvas.save(OUT/f'comparison-{v}.jpg',quality=94)
cards=''.join(f'<figure><figcaption>{title}</figcaption><a id="link-{key}" href="{key}-V02.png"><img id="{key}" src="{key}-V02.png"></a></figure>' for key,title in [('firewatch-medium','Previous Medium'),('evergreen','Coordinated palette and crown lighting')])
html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>LiDAR evergreen art direction</title><style>body{background:#11201e;color:#eee9d8;font:17px/1.6 system-ui;margin:28px}h1{font-size:30px}a{color:#bad8b5}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}figure{margin:0}img{width:100%;display:block}figcaption{padding:10px 0}p{max-width:1100px}select{padding:10px;background:#293d34;color:white}td,th{text-align:left;padding:10px;border-bottom:1px solid #536453}code{color:#d5d6a5}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style><h1>Warm light over cool evergreen valleys</h1><p>Actual standalone game captures at the same 1600 × 900 camera, exposure and graphics settings. The coordinated pass uses Medium’s haze range and intensity, adding a shared palette for the sky, canopy and clearings. Close-up material detail is retained.</p><label>View <select id="view"><option value="V02">Main valley</option><option value="V01">Wide view</option><option value="V03">Second long view</option><option value="G01">Ground-level protection view</option></select></label><div class="grid">'''+cards+'''</div><div class="grid"><figure><figcaption>Firewatch / Campo Santo</figcaption><img src="firewatch.jpg"></figure><figure><figcaption>Original supplied reference</figcaption><img src="original.jpg"></figure></div><p>Firewatch image: <a href="https://www.pcgamer.com/firewatch-gallery-a-colorful-tour-of-shoshone-national-forest/">PC Gamer gallery</a>. These references guide different aspects of the scene; they are not game captures from this project.</p><h2 id="tuning">Adjust the look per map</h2><p>Select <code>LidarStudy_DistanceStyle</code>, then open its <code>Profile</code>: <code>DA_Lidar_Evergreen</code> in <code>/Game/GrandTour/ArtTests/LidarStudy/CohesiveStyle</code>. Duplicate that profile for independent map art direction. Use one controller per persistent map and bind that map’s sun. Preview with viewport Realtime enabled, or press Apply Profile; save the profile to retain changes.</p><table><tr><th>Controls</th><th>What changes</th></tr><tr><td>Art Direction / Palette Strength, Start and Full Metres</td><td>Shared palette amount and its distance transition.</td></tr><tr><td>Sunlit Colour, Forest Colour, Shadow Colour</td><td>Warm crown highlights, evergreen body colour and cool shadows.</td></tr><tr><td>Crown Definition</td><td>Retains crown lighting shape through distance simplification.</td></tr><tr><td>Clearing Colour / Clearing Shadow Colour</td><td>Quieter open grassland colours, using the existing land-cover mask.</td></tr><tr><td>Sky Palette Strength / Horizon Colour / Zenith Colour</td><td>A direction-based sky gradient that follows camera pitch.</td></tr><tr><td>Haze Colour / Intensity / Start / Full</td><td>Independent distant haze. Existing low forest and river fog remains separate.</td></tr></table><p>To compare the previous look in the same map, assign <code>DA_Lidar_Medium</code> to Profile. Its new palette and sky strengths are zero. New terrain still needs its own canopy lighting field and map bounds; the current field is specific to LiDAR. Sky and haze colours target the current SDR presentation.</p><p><a href="evidence.json">Validation and performance evidence</a></p><p>Performance timings are unverified while Skate shares the GPU. This review covers four fixed views; moving-camera validation remains pending.</p><script>document.getElementById('view').onchange=e=>{for(const k of ['firewatch-medium','evergreen']){let p=k+'-'+e.target.value+'.png';document.getElementById(k).src=p;document.getElementById('link-'+k).href=p}}</script>'''
(OUT/'index.html').write_text(html,encoding='utf-8');print(OUT/'comparison-V02.jpg')
